"""Auto-discover and test generated fixtures from /debug-pdf, /debug-table, /fixture-tricky.

This module discovers all PDFs in tests/fixtures/generated/ and runs extraction
tests on them. Each fixture has an associated YAML manifest describing:
- Expected behavior (should_extract_tables, expected_table_count, etc.)
- Known issues (false_positives, fragmentation, etc.)
- Source skill that generated it

Fixtures are generated by skills and should NOT be manually created here.
"""

import json
import pytest
from pathlib import Path
from typing import Any

import yaml

# Fixture directory
FIXTURE_DIR = Path(__file__).parent
MANIFEST_FILE = FIXTURE_DIR / "manifest.yaml"


def load_manifest() -> dict[str, Any]:
    """Load the fixture manifest."""
    if not MANIFEST_FILE.exists():
        return {"fixtures": []}
    return yaml.safe_load(MANIFEST_FILE.read_text()) or {"fixtures": []}


def get_fixture_pdfs() -> list[tuple[Path, dict]]:
    """Get all fixture PDFs with their expected behaviors."""
    manifest = load_manifest()
    fixtures = []

    for entry in manifest.get("fixtures", []):
        pdf_path = FIXTURE_DIR / entry["filename"]
        if pdf_path.exists():
            fixtures.append((pdf_path, entry))

    return fixtures


# Parametrize tests based on manifest
fixture_data = get_fixture_pdfs()


@pytest.mark.skipif(not fixture_data, reason="No generated fixtures found")
@pytest.mark.parametrize("pdf_path,expected", fixture_data, ids=[f[1]["name"] for f in fixture_data] if fixture_data else [])
class TestGeneratedFixtures:
    """Test suite for auto-generated fixtures."""

    def test_table_extraction(self, pdf_path: Path, expected: dict, tmp_path: Path):
        """Test table extraction on fixture."""
        # Apply xfail if marked in manifest (known bugs being tracked)
        if expected.get("xfail"):
            pytest.xfail(expected.get("xfail_reason", "Known failure"))

        from extractor.pipeline.steps import s05_table_extractor as s05

        output_dir = tmp_path / "s05"
        output_dir.mkdir()

        tables, strategy_summary, quality_summary = s05.extract_all_tables(
            pdf_path, output_dir
        )

        # Check expected table count if specified
        if "expected_table_count" in expected:
            assert len(tables) == expected["expected_table_count"], \
                f"Expected {expected['expected_table_count']} tables, got {len(tables)}"

        # Check for false positives
        if expected.get("should_have_no_tables", False):
            assert len(tables) == 0, \
                f"Expected no tables (false positive test), got {len(tables)}"

        # Check fragmentation threshold
        if "max_fragmentation" in expected:
            fragmented = sum(1 for t in tables if t.get("rows", 0) < 2)
            frag_pct = (fragmented / len(tables) * 100) if tables else 0
            assert frag_pct <= expected["max_fragmentation"], \
                f"Fragmentation {frag_pct}% exceeds max {expected['max_fragmentation']}%"

    def test_section_detection(self, pdf_path: Path, expected: dict, tmp_path: Path):
        """Test section detection on fixture."""
        if not expected.get("test_sections", False):
            pytest.skip("Section testing not enabled for this fixture")

        from extractor.pipeline.steps import s00_profile_detector as s00

        output_dir = tmp_path / "s00"
        output_dir.mkdir()

        result_path = s00.run(pdf_path, output_dir)
        result = json.loads(result_path.read_text())

        # Check expected section count if specified
        if "expected_section_count" in expected:
            actual = result.get("estimated_sections", 0)
            assert actual == expected["expected_section_count"], \
                f"Expected {expected['expected_section_count']} sections, got {actual}"

    def test_profile_detection(self, pdf_path: Path, expected: dict, tmp_path: Path):
        """Test profile/preset detection on fixture."""
        if not expected.get("test_profile", False):
            pytest.skip("Profile testing not enabled for this fixture")

        from extractor.pipeline.steps import s00_profile_detector as s00

        output_dir = tmp_path / "s00"
        output_dir.mkdir()

        result_path = s00.run(pdf_path, output_dir)
        result = json.loads(result_path.read_text())

        # Check expected domain
        if "expected_domain" in expected:
            assert result.get("domain") == expected["expected_domain"], \
                f"Expected domain {expected['expected_domain']}, got {result.get('domain')}"

    def test_requirements_extraction(self, pdf_path: Path, expected: dict, tmp_path: Path):
        """Test requirements extraction on fixtures with requirements tags."""
        tags = expected.get("tags", [])
        if "requirements" not in tags and "s08" not in tags:
            pytest.skip("Requirements testing not enabled for this fixture")

        # Only test fixtures specifically designed for requirements
        if not any(tag in tags for tag in ["requirements", "s08"]):
            pytest.skip("Not a requirements fixture")

        from extractor.pipeline.steps.s08_extract_requirements import extract_requirements_deterministic
        import fitz

        # Extract text from PDF for requirements detection
        doc = fitz.open(str(pdf_path))
        full_text = ""
        for page in doc:
            full_text += page.get_text()
        doc.close()

        # Run deterministic extraction (regex-based)
        requirements = extract_requirements_deterministic(full_text)

        # Check expected requirement count if specified
        if "expected_requirement_count" in expected:
            expected_count = expected["expected_requirement_count"]
            # Allow some tolerance for complex fixtures
            tolerance = max(5, expected_count * 0.3)  # 30% tolerance or min 5
            assert abs(len(requirements) - expected_count) <= tolerance, \
                f"Expected ~{expected_count} requirements (±{tolerance}), got {len(requirements)}"

        # Check for false positives (should have NO requirements)
        if expected.get("should_have_no_requirements", False):
            # For false positive tests, allow very few (<=2) due to regex edge cases
            assert len(requirements) <= 2, \
                f"Expected no requirements (false positive test), got {len(requirements)}: {[r.get('text', '')[:50] for r in requirements]}"


def test_manifest_integrity():
    """Verify all fixtures in manifest exist."""
    manifest = load_manifest()
    missing = []

    for entry in manifest.get("fixtures", []):
        pdf_path = FIXTURE_DIR / entry["filename"]
        if not pdf_path.exists():
            missing.append(entry["filename"])

    assert not missing, f"Missing fixture files: {missing}"
